"""Explicit environment/robot structural contact materials.

These values are layer-level project decisions, not task tuning knobs. Task
objects continue to use tasks.config.object_materials.
"""

from __future__ import annotations

import re

import sapien.physx as physx


TABLE_FRICTION = 0.30
SHARPA_NONPAD_FRICTION = 0.35
# Same value for every dexterous hand's non-pad shell (four-layer contract L2).
HAND_NONPAD_FRICTION = SHARPA_NONPAD_FRICTION
ROBOT_STRUCTURE_FRICTION = 0.30
STRUCTURE_RESTITUTION = 0.0


_SHARPA_HAND_PREFIXES = tuple(
    f"{side}_{part}_"
    for side in ("left", "right")
    for part in ("hand", "thumb", "index", "middle", "ring", "pinky")
)

# Wuji names every hand link `<side>_finger{1..5}_*` plus `<side>_palm_link`;
# XHand names them all `<side>_hand_*`.
_WUJI_HAND_PREFIXES = tuple(
    f"{side}_{part}" for side in ("left", "right")
    for part in ("finger", "palm_link")
)
_XHAND_HAND_PREFIXES = tuple(f"{side}_hand_" for side in ("left", "right"))


_PANDA_ARM_LINK = re.compile(r"panda_link[0-8]")
_MOBILE_BASE_LINK = re.compile(r"mobile_base_link_[0-9]+")
_PANDA_STRUCTURE_LINKS = {
    "panda_hand",
    "mobile_base",
    "mobile_base_model",
    "trapezoid_base",
    "angle_bracket",
    "hand_docking_link",
}


def _material(friction: float) -> physx.PhysxMaterial:
    return physx.PhysxMaterial(
        float(friction), float(friction), STRUCTURE_RESTITUTION
    )


def _collision_shapes(obj):
    """Return shapes from a PhysX link component or a SAPIEN Entity."""
    if hasattr(obj, "get_collision_shapes"):
        return list(obj.get_collision_shapes())
    shapes = []
    for component in getattr(obj, "components", ()):
        if hasattr(component, "get_collision_shapes"):
            shapes.extend(component.get_collision_shapes())
    return shapes


def _set_struct_material(struct, material: physx.PhysxMaterial) -> int:
    """Assign material to every collision shape in a merged ManiSkill struct."""
    count = 0
    for obj in struct._objs:
        for shape in _collision_shapes(obj):
            shape.set_physical_material(material)
            count += 1
    return count


def apply_table_contact_material(table_scene) -> int:
    """Explicitly materialize the approved table/ground 0.30 profile."""
    material = _material(TABLE_FRICTION)
    return sum(
        _set_struct_material(actor, material)
        for actor in (table_scene.table, table_scene.ground)
    )


def _without_side_prefix(link_name: str) -> str:
    for prefix in ("left_", "right_"):
        if link_name.startswith(prefix):
            return link_name[len(prefix) :]
    return link_name


def is_panda_structure_link(link_name: str) -> bool:
    """Whether a link belongs to Franka, its mount, or its mobile base.

    This intentionally uses a narrow allow-list. Hand/finger links belonging to
    Sharpa, Wuji, SoftHand, Shadow, XHand, or the stock gripper are not selected,
    so their own contact-material decisions remain untouched.
    """
    name = _without_side_prefix(str(link_name))
    return bool(
        _PANDA_ARM_LINK.fullmatch(name)
        or _MOBILE_BASE_LINK.fullmatch(name)
        or name in _PANDA_STRUCTURE_LINKS
    )


def apply_panda_structure_contact_material(robot) -> dict[str, object]:
    """Freeze all collidable Panda/mount/base shapes at the approved 0.30.

    Returns an auditable count and the touched link names. A missing collidable
    Panda arm is treated as a wiring error instead of silently falling back.
    """
    material = _material(ROBOT_STRUCTURE_FRICTION)
    shape_count = 0
    arm_shape_count = 0
    touched_links: list[str] = []
    for link in robot.get_links():
        name = str(link.name)
        if not is_panda_structure_link(name):
            continue
        count = _set_struct_material(link, material)
        if count == 0:
            continue
        touched_links.append(name)
        shape_count += count
        if _PANDA_ARM_LINK.fullmatch(_without_side_prefix(name)):
            arm_shape_count += count
    if arm_shape_count == 0:
        raise RuntimeError(
            "Panda structure material wrapper found no collidable panda_link0..8"
        )
    return {
        "robot_structure": shape_count,
        "arm_structure": arm_shape_count,
        "structure_links": tuple(touched_links),
    }


def apply_sharpa_robot_contact_materials(robot, grip_link_names) -> dict[str, int]:
    """Assign structure materials without touching elastomer/DP grip links.

    grip_link_names already carry the frozen 1.2 fingertip material and 5/2 mm
    patch radii through urdf_config. Every other Sharpa hand link gets 0.35;
    Panda links, brackets and mobile-base links get 0.30.
    """
    grip_names = set(grip_link_names)
    seen_grip_names: set[str] = set()
    hand_material = _material(SHARPA_NONPAD_FRICTION)
    structure_counts = apply_panda_structure_contact_material(robot)
    counts = {
        "grip_untouched": 0,
        "hand_structure": 0,
        "robot_structure": int(structure_counts["robot_structure"]),
    }

    for link in robot.get_links():
        name = str(link.name)
        shape_count = sum(
            len(_collision_shapes(obj)) for obj in link._objs
        )
        if shape_count == 0:
            continue
        if name in grip_names:
            seen_grip_names.add(name)
            counts["grip_untouched"] += shape_count
            continue
        if name.startswith(_SHARPA_HAND_PREFIXES):
            counts["hand_structure"] += _set_struct_material(
                link, hand_material
            )

    missing = grip_names - seen_grip_names
    if missing:
        raise RuntimeError(
            "Sharpa grip links have no collision shapes: "
            + ", ".join(sorted(missing))
        )
    return counts


def apply_dex_hand_contact_materials(robot, grip_link_names, hand_prefixes,
                                     hand_label="hand") -> dict[str, int]:
    """Generic form of ``apply_sharpa_robot_contact_materials`` for any dexterous
    hand: the pads listed in ``grip_link_names`` keep the 1.2 material they got
    from ``urdf_config``, every other link of that hand is stated at
    ``HAND_NONPAD_FRICTION``, and Panda/mount/base links get the 0.30 structure
    material from the shared hook.

    Stating the shell matters: left implicit it falls back to the engine's 0.30
    with ZERO torsional friction, and the pads-only material lists this project
    shipped meant the links that actually carry a grasp were on that fallback.
    """
    grip_names = set(grip_link_names)
    seen_grip_names: set[str] = set()
    hand_material = _material(HAND_NONPAD_FRICTION)
    structure_counts = apply_panda_structure_contact_material(robot)
    counts = {"grip_untouched": 0, "hand_structure": 0,
              "robot_structure": int(structure_counts["robot_structure"])}

    for link in robot.get_links():
        name = str(link.name)
        shape_count = sum(len(_collision_shapes(obj)) for obj in link._objs)
        if shape_count == 0:
            continue
        if name in grip_names:
            seen_grip_names.add(name)
            counts["grip_untouched"] += shape_count
            continue
        if name.startswith(tuple(hand_prefixes)) and not is_panda_structure_link(name):
            counts["hand_structure"] += _set_struct_material(link, hand_material)

    missing = grip_names - seen_grip_names
    if missing:
        raise RuntimeError(
            f"{hand_label} grip links have no collision shapes: " + ", ".join(sorted(missing))
        )
    return counts


def apply_wuji_robot_contact_materials(robot, grip_link_names) -> dict[str, int]:
    return apply_dex_hand_contact_materials(
        robot, grip_link_names, _WUJI_HAND_PREFIXES, hand_label="Wuji")


def apply_xhand_robot_contact_materials(robot, grip_link_names) -> dict[str, int]:
    return apply_dex_hand_contact_materials(
        robot, grip_link_names, _XHAND_HAND_PREFIXES, hand_label="XHand")
